{
  "findings": [
    {
      "check_id": "CKV_AWS_261",
      "title": "Ensure HTTP HTTPS Target group defines Healthcheck",
      "resource": "aws_lb_target_group.pass",
      "severity": "MEDIUM",
      "explanation": "The aws_lb_target_group 'pass' is missing a health check configuration, which is necessary for monitoring the health of the target group."
    }
  ],
  "patched_code": "resource \"aws_lb_target_group\" \"pass\" {\n  name        = \"tf-example-lb-alb-tg\"\n  target_type = \"alb\"\n  port        = 80\n  protocol    = \"TCP\"\n  vpc_id      = aws_vpc.main.id\n  health_check {\n    enabled = true\n    protocol = \"TCP\"\n    port     = \"traffic-port\"\n  }\n}",
  "fix_summary": "Added a health check configuration to the aws_lb_target_group 'pass' to ensure its health is monitored."
}
